-p-blur-sm:blur(3px);--p-blur-md:blur(16px);--p-blur-glass:blur(20px) saturate(1.2);}
.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-type-body);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ui-icon { display:inline-block; width:var(--p-icon-md); height:var(--p-icon-md); flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:var(--p-size-md-plus); color:var(--p-muted); }
.ds .ds-surface { border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:var(--p-blur-md); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }
.ds .ds-token-row { display:flex; flex-wrap:wrap; align-items:center; gap:var(--p-space-sm); }

.ds .ds-page { max-width:var(--p-container-3xl); margin-inline:auto; }
.ds .ds-page-header { display:flex; justify-content:space-between; align-items:center; gap:var(--p-space-md); margin-bottom:var(--p-space-xl); }
.ds .ds-page-header h2 { font-size:var(--p-text-heading-xl); font-weight:var(--p-weight-semibold-plus); letter-spacing:var(--p-tracking-display); margin-top:var(--p-space-xs); }
.ds .ds-eyebrow { font-size:var(--p-text-sm); color:var(--p-muted); }
.ds .ds-page > .ds-bottom-nav { margin:var(--p-space-xl) auto 0; max-width:var(--p-container-sm); }
/* Looks: how the screen opens. Each look also brings its own bottom bar shape from the markup. */
.ds .ds-page[data-look="hero"] .ds-page-header { align-items:flex-end; padding:var(--p-space-lg-plus) var(--p-space-md-plus) var(--p-space-md-plus); border-radius:var(--p-radius); background:var(--p-soft); }
.ds .ds-page[data-look="hero"] .ds-page-header h2 { font-size:var(--p-text-display); line-height:var(--p-leading-tight); }
.ds .ds-page[data-look="appbar"] .ds-page-header { position:relative; justify-content:center; padding:var(--p-space-3xs) var(--p-space-5xl) var(--p-space-md); margin-bottom:var(--p-space-lg); border-bottom:var(--p-border-width) solid var(--p-line); text-align:center; }
.ds .ds-page[data-look="appbar"] .ds-page-header h2 { margin-top:0; font-size:var(--p-text-title); letter-spacing:var(--p-tracking-tight); }
.ds .ds-page[data-look="appbar"] .ds-page-header > .ds-badge { position:absolute; right:0; top:50%; translate:0 calc(var(--p-fill-md) * -1); }
.ds .ds-page[data-look="sheet"] .ds-page-header { align-items:flex-start; margin-bottom:0; padding:var(--p-space-lg) var(--p-space-md-plus) var(--p-space-5xl); border-radius:var(--p-radius) var(--p-radius) 0 0; background:var(--p-accent); color:var(--p-on-accent); }
.ds .ds-page[data-look="sheet"] .ds-page-header .ds-eyebrow { color:var(--p-on-accent-muted); }
.ds .ds-page[data-look="sheet"] .ds-page-header + * { position:relative; margin-top:calc(var(--p-space-xl) * -1); padding:var(--p-space-lg) var(--p-space-md-plus); border-radius:var(--p-radius-lg) var(--p-radius-lg) 0 0; background:var(--p-high); }
.ds .ds-page[data-look="dashboard"] .ds-page-header { margin-bottom:var(--p-space-md); }
.ds .ds-page-stats { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:var(--p-space-xs); margin:0 0 var(--p-space-lg); padding:0; list-style:none; }
.ds .ds-page-stats li { display:grid; gap:var(--p-space-4xs); padding:var(--p-space-sm); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius-md); background:var(--p-surface); }
.ds .ds-page-stats strong { font:var(--p-type-stat); letter-spacing:var(--p-tracking-tight); }
.ds .ds-page-stats span { font-size:var(--p-text-label); color:var(--p-muted); }
.ds .ds-template-slot { min-height:var(--p-panel-h-3xs); display:grid; place-items:center; padding:var(--p-space-lg); border:var(--p-border-width) var(--p-stroke-dashed) var(--p-control-border); border-radius:var(--p-radius); color:var(--p-muted); font-size:var(--p-text-body); }

.ds .ds-badge { display:inline-flex; align-items:center; width:fit-content; padding:var(--p-space-3xs) var(--p-space-xs-plus); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius-full); background:var(--p-soft); color:var(--p-ink); font-size:var(--p-text-label); line-height:var(--p-leading-normal); font-weight:var(--p-weight-semibold); }
.ds .ds-badge[data-tone="success"] { background:var(--p-success-soft); border-color:var(--p-success-line); color:var(--p-success); }
.ds .ds-badge[data-tone="error"] { background:var(--p-error-soft); border-color:var(--p-error-line); color:var(--p-error); }
.ds .ds-badge[data-tone="warning"] { background:var(--p-warning-soft); border-color:var(--p-warning-line); color:var(--p-warning); }
/* looks: tone keeps the color, look changes the shape */
.ds .ds-badge[data-look="icon"] { gap:var(--p-space-3xs); padding-left:var(--p-space-xs); }
.ds .ds-badge[data-look="icon"] .ui-icon { width:var(--p-icon-2xs); height:var(--p-icon-2xs); stroke-width:var(--p-icon-stroke-heavy); }
/* count: a number pinned to the icon corner, so nobody opens the box to count what piled up */
.ds .ds-badge[data-look="count"] { position:relative; display:inline-grid; place-items:center; width:var(--p-control-size-sm); height:var(--p-control-size-sm); padding:0; border:0; background:transparent; color:var(--p-ink); }
.ds .ds-badge[data-look="count"] .ui-icon { width:var(--p-icon-xl); height:var(--p-icon-xl); }
.ds .ds-badge-count { position:absolute; top:var(--p-space-4xs); right:0; display:inline-grid; place-items:center; min-width:var(--p-size-md-plus); height:var(--p-size-md-plus); padding:0 var(--p-space-3xs); border-radius:var(--p-radius-full); background:var(--p-accent); color:var(--p-on-accent); box-shadow:0 0 0 var(--p-border-width-strong) var(--p-bg); font-size:var(--p-text-label); font-weight:var(--p-weight-bold); line-height:var(--p-leading-none); font-variant-numeric:tabular-nums; }

.ds .ds-search-module { container-type:inline-size; }
.ds .ds-search-form { display:grid; grid-template-columns:minmax(0,1fr) minmax(calc(var(--p-size-6xl) + var(--p-size-xs-plus)),.3fr) auto; align-items:end; gap:var(--p-space-sm); }
.ds .ds-result-count { font-size:var(--p-text-sm); color:var(--p-muted); margin-block:var(--p-space-lg) var(--p-space-md); }
.ds .ds-results { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,var(--p-column-sm)),1fr)); gap:var(--p-space-lg); }
.ds .ds-empty { padding:var(--p-space-xl); text-align:center; border:var(--p-border-width) var(--p-stroke-dashed) var(--p-control-border); border-radius:var(--p-radius); }
.ds .ds-empty .ds-button { margin-top:var(--p-space-md); }
.ds .ds-record-detail { padding:var(--p-space-lg); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-record-detail h3 { font-size:var(--p-text-lg); font-weight:var(--p-weight-semibold-plus); }
.ds .ds-record-detail p { margin-top:var(--p-space-sm); color:var(--p-muted); }
.ds .ds-record-detail > div { display:flex; flex-wrap:wrap; gap:var(--p-space-sm); margin-top:var(--p-space-lg); }
.ds .ds-record-detail [aria-pressed="true"] { background:var(--p-success); border-color:var(--p-success); }
@media(max-width:580px) { .ds .ds-search-form { grid-template-columns:minmax(0,1fr) auto; } .ds .ds-search-form > .ds-field { grid-column:1/-1; } }
@container(max-width:580px) { .ds .ds-search-form { grid-template-columns:minmax(0,1fr) auto; } .ds .ds-search-form > .ds-field { grid-column:1/-1; } }
/* Looks. Labels hidden by a look stay in the page for screen readers. */
.ds .ds-search-module[data-look="pill"] :is(.ds-field > label,.ds-select-field > span),.ds .ds-chip-group > legend,.ds .ds-chip input { position:absolute; width:var(--p-size-hairline); height:var(--p-size-hairline); overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
/* 02 pill: query, status and button share one rounded bar */
.ds .ds-search-module[data-look="pill"] .ds-search-form { grid-template-columns:minmax(0,1fr) auto auto; align-items:center; gap:var(--p-space-3xs); padding:var(--p-space-3xs) var(--p-space-3xs) var(--p-space-3xs) var(--p-space-sm); border:var(--p-border-width) solid var(--p-control-border); border-radius:var(--p-radius-full); background:var(--p-bg); box-shadow:var(--p-inset); }
.ds .ds-search-module[data-look="pill"] .ds-search-form > .ds-field { grid-column:auto; }
.ds .ds-search-module[data-look="pill"] .ds-search-form .ds-input { border:0; background:transparent; box-shadow:none; }
.ds .ds-search-module[data-look="pill"] .ds-search-form select.ds-input { width:auto; padding-inline:var(--p-space-sm) var(--p-space-xs); border-left:var(--p-border-width) solid var(--p-line); border-radius:0; }
.ds .ds-search-module[data-look="pill"] .ds-search-form > .ds-button { border-radius:var(--p-radius-full); }
@container(max-width:420px) { .ds .ds-search-module[data-look="pill"] .ds-search-form > .ds-button { gap:0; padding-inline:var(--p-space-sm); font-size:0; } }
/* 03 chips: status as a row of chips under the query */
.ds .ds-search-module[data-look="chips"] .ds-search-form { grid-template-columns:minmax(0,1fr) auto; }
.ds .ds-search-module[data-look="chips"] .ds-search-form > .ds-field { grid-column:auto; }
.ds .ds-chip-group { grid-column:1/-1; order:3; display:flex; flex-wrap:wrap; gap:var(--p-space-xs); min-width:0; margin:0; padding:0; border:0; }
.ds .ds-chip { position:relative; display:inline-flex; align-items:center; gap:var(--p-space-2xs); min-height:var(--p-control-size-sm); padding:0 var(--p-space-md); border:var(--p-border-width) solid var(--p-control-border); border-radius:var(--p-radius-full); background:var(--p-bg); font-size:var(--p-text-body); cursor:pointer; }
.ds .ds-chip:has(:checked) { border-color:var(--p-accent); background:var(--p-accent); color:var(--p-on-accent); font-weight:var(--p-weight-semibold-plus); }
.ds .ds-chip:has(:checked)::before { content:'✓'; font-weight:var(--p-weight-bold); }
.ds .ds-chip:has(:focus-visible) { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
/* list: results as rows instead of tiles */
.ds .ds-search-module[data-look="list"] .ds-results { grid-template-columns:minmax(0,1fr); gap:0; }
.ds .ds-search-module[data-look="list"] .ds-card { flex-flow:row wrap; align-items:center; border:0; border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-search-module[data-look="list"] .ds-card-body { flex:1 1 var(--p-column-3xs); padding:var(--p-space-sm-plus) 0; }
.ds .ds-search-module[data-look="list"] .ds-card h3 { margin-top:var(--p-space-3xs); font-size:var(--p-text-md); }
.ds .ds-search-module[data-look="list"] .ds-divider { display:none; }
.ds .ds-search-module[data-look="list"] .ds-card-actions { padding:var(--p-space-xs) 0 var(--p-space-xs) var(--p-space-sm); }
.ds .ds-search-module[data-look="list"] .ds-results { border-top:var(--p-border-width) solid var(--p-line); }
.ds .ds-search-module[data-look="list"] .ds-card { border-bottom:var(--p-border-width) solid var(--p-line); }
/* 07 feature: the first result spans the row with a bigger title */
.ds .ds-search-module[data-look="feature"] .ds-results > :first-child { grid-column:1/-1; }
.ds .ds-search-module[data-look="feature"] .ds-results > :first-child h3 { font-size:var(--p-text-heading-sm); line-height:var(--p-leading-compact); }
/* picker: one field that narrows while typing; every result is a face row tapped as a whole */
.ds .ds-search-module[data-look="picker"] .ds-search-form { grid-template-columns:minmax(0,1fr); }
