'use client';
import React from 'react';
import { Template } from './template.jsx';
import { SearchModule } from './search-module.jsx';
// Each screen look brings the bottom bar shape and search look that suit it, the same pairs the HTML renderer uses.
// Pass a <BottomNav variant={pageLooks[look].navigation} /> as navigation to complete the screen.
export const pageLooks = { stack: { navigation: 'minimal', search: 'grid' }, hero: { navigation: 'pill', search: 'pill' }, appbar: { navigation: 'line', search: 'list' }, sheet: { navigation: 'glass', search: 'chips' }, dashboard: { navigation: 'float', search: 'list' } };
export function CollectionPage({ title = '컬렉션', records, onSave, look = 'stack', navigation }) {
  const pair = pageLooks[look] ?? pageLooks.stack;
  const list = records ?? [{ tag: '진행 중' }, { tag: '완료' }, { tag: '진행 중' }];
  const summary = [['전체', `${list.length}개`], ...['진행 중', '완료'].map(tag => [tag, `${list.filter(item => item.tag === tag).length}개`])];
  return <Template title={title} count={`${list.length}개`} look={pageLooks[look] ? look : 'stack'} summary={summary} navigation={navigation}><SearchModule records={records} onSave={onSave} look={pair.search} /></Template>;
}

import React from 'react';
import { Badge } from './badge.jsx';
// look matches the HTML data-look values; the dashboard look shows the summary numbers under the header.
export function Template({ title = '컬렉션', eyebrow = '나의 작업실', count, children, navigation, look = 'stack', summary = [] }) {
  return <div className="ds-page" data-look={look}><header className="ds-page-header"><div><span className="ds-eyebrow">{eyebrow}</span><h2>{title}</h2></div>{count && <Badge>{count}</Badge>}</header>{look === 'dashboard' && summary.length > 0 && <ul className="ds-page-stats" role="list">{summary.map(([label, value]) => <li key={label}><strong>{value}</strong><span>{label}</span></li>)}</ul>}{children}{navigation}</div>;
}

import React from 'react';
// The count look pins how many new items wait on the icon (children); the number is read as "새 알림 N개" and hides at zero.
export function Badge({ children, tone = 'neutral', look, count, ...props }) {
  if (look === 'count') return <span role="img" aria-label={count > 0 ? `새 알림 ${count}개` : '새 알림 없음'} {...props} className="ds-badge" data-tone={tone} data-look="count">{children}{count > 0 && <span className="ds-badge-count" aria-hidden="true">{count > 99 ? '99+' : count}</span>}</span>;
  return <span {...props} className="ds-badge" data-tone={tone} data-look={look}>{children}</span>;
}

