  const status = look === 'chips'
    ? <fieldset className="ds-chip-group"><legend>상태</legend>{statuses.map(([value, label]) => <label key={value} className="ds-chip"><input type="radio" name="status" value={value} defaultChecked={value === 'all'} onChange={pick} /><span>{label}</span></label>)}</fieldset>
    : <label className="ds-select-field" htmlFor={`${id}-status`}><span>상태</span><select id={`${id}-status`} className="ds-input" name="status" onChange={pick}>{statuses.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>;
  return <section className="ds-search-module" data-look={look} aria-label="컬렉션 검색"><div hidden={!!selected}><form ref={form} className="ds-search-form" onSubmit={search}>{picker ? <Field label="컬렉션 찾기" name="query" type="search" placeholder="이름 한두 글자" onChange={live} /> : <><Field label="컬렉션 검색" name="query" placeholder="이름으로 검색" />{status}<Button type="submit">검색</Button></>}</form><p className="ds-result-count" role="status">{filtered.length}개의 컬렉션</p><div className="ds-results">{filtered.map((item, index) => <div key={item.id}><Card look={cardLook(index)} initial={picker ? [...item.title][0] : ''}><CardBody><Badge>{item.tag}</Badge><CardTitle>{item.title}</CardTitle><CardDescription>{item.description}</CardDescription></CardBody><CardActions><Button variant="outline" size="sm" onClick={event => open(item, event)}>{picker ? '고르기' : '열기'}</Button></CardActions></Card></div>)}</div>{!filtered.length && <div className="ds-empty"><p>일치하는 컬렉션이 없어요.</p><Button variant="outline" onClick={() => { form.current.reset(); setFilter({ query: '', status: 'all' }); form.current.elements.query.focus(); }}>전체 보기</Button></div>}</div>{selected && <section ref={detail} className="ds-record-detail" aria-label="컬렉션 상세" tabIndex={-1}><h3>{selected.title}</h3><p>{selected.description}</p><div><Button variant="outline" onClick={close}>목록으로</Button><Button loading={busy} aria-pressed={saved.includes(selected.id)} onClick={save}>{saved.includes(selected.id) ? '보관됨' : '컬렉션에 보관'}</Button></div><p role="status">{message}</p></section>}</section>;
}

'use client';
import React, { useId } from 'react';
import { Input } from './input.jsx';
export function FieldLabel({ htmlFor, children, ...props }) { return <label {...props} htmlFor={htmlFor}>{children}</label>; }
export function FieldDescription({ id, children, ...props }) { return <p {...props} className="ds-help" id={id}>{children}</p>; }
export function Field({ id: suppliedId, look, label, help, error, state, children, ...props }) {
  const generatedId = useId(); const id = suppliedId || generatedId;
  const description = error || help;
  const inputProps = { ...props, id, 'aria-invalid': error ? true : undefined, 'aria-describedby': [props['aria-describedby'], description ? `${id}-help` : ''].filter(Boolean).join(' ') || undefined };
  return <div className="ds-field" data-look={look} data-state={error ? 'error' : props.disabled ? 'disabled' : state}>
    <FieldLabel htmlFor={id}>{label}</FieldLabel>
    {children ? children(inputProps) : <Input {...inputProps} />}
    {description && <FieldDescription id={`${id}-help`}>{description}</FieldDescription>}
  </div>;
}

'use client';
import React, { useState } from 'react';
export function Input({ look, className = '', ...props }) { return <input {...props} className={`ds-input ${className}`} data-look={look} />; }
// The clear, unit and stepper looks keep the helper inside the same box:
// <InputGroup look="clear"><Input /><InputTool aria-label="지우기">…</InputTool></InputGroup>
export function InputGroup({ look, children, ...props }) { return <span {...props} className="ds-input-group" data-look={look}>{children}</span>; }
export function InputTool({ children, ...props }) { return <button type="button" {...props} className="ds-input-tool">{children}</button>; }
// The field row look joins a start and an end value in one box with this mark between them.
// The reveal look flips the typed secret to plain text in place, so a typo is seen instead of retyped.
export function PasswordInput({ label = '비밀번호', disabled, ...props }) {
  const [shown, setShown] = useState(false);
  return <InputGroup look="reveal"><Input {...props} disabled={disabled} type={shown ? 'text' : 'password'} /><InputTool aria-label={`${label} ${shown ? '숨기기' : '보기'}`} disabled={disabled} onClick={() => setShown(!shown)}>{shown ? '숨기기' : '보기'}</InputTool></InputGroup>;
}
export function InputJoin({ children = '~' }) { return <span className="ds-input-join" aria-hidden="true">{children}</span>; }

import React from 'react';
// count joins the accessible name ("보내기 3개") and shows as a small number next to the label.
export function Button({ children, look, count, variant = 'primary', size = 'md', loading = false, disabled, className = '', type = 'button', ...props }) {
  const named = count != null && typeof children === 'string' ? `${children} ${count}개` : undefined;
  return <button {...props} type={type} className={`ds-button ${className}`} data-variant={variant} data-size={size} data-look={look} disabled={disabled || loading} aria-busy={loading || undefined} aria-label={props['aria-label'] ?? named}>
    {loading && <span className="ds-spinner" aria-hidden="true" />}{children}{count != null && <span className="ds-button-count" aria-hidden="true">{count}</span>}
  </button>;
}
// The hero, pair and bar looks are arrangements of several buttons: wrap them in Actions with that look.
export function Actions({ look = 'hero', children, ...props }) { return <div {...props} className="ds-actions" data-look={look}>{children}</div>; }

import React from 'react';
import { Divider } from './divider.jsx';
// look matches the HTML data-look values; the media and row looks put a picture area before the body,
// and initial prints a letter in it when there is no picture (the picker's face rows).
export function Card({ children, look = 'raised', initial = '', ...props }) { return <article {...props} className="ds-card" data-look={look}>{(look === 'media' || look === 'row') && <div className="ds-card-media" aria-hidden="true">{initial}</div>}{children}</article>; }
export function CardBody({ children }) { return <div className="ds-card-body">{children}</div>; }
export function CardTitle({ children, as: Tag = 'h3' }) { return <Tag>{children}</Tag>; }
export function CardDescription({ children }) { return <p>{children}</p>; }
export function CardActions({ children }) { return <><Divider /><footer className="ds-card-actions">{children}</footer></>; }

